rust_translation:
pub fn validate_plugin_usage(plugin_usages: &[PluginUsage]) -> Result<(), String> {
    let name_re = Regex::new(r"^[A-Za-z][A-Za-z0-9]*$").unwrap();
    let semver_re = Regex::new(r"^\d+\.\d+\.\d+$").unwrap();

    for plugin in plugin_usages {
        // Validate plugin name format
        if !name_re.is_match(&plugin.plugin_name) {
            return Err(format!(
                "Invalid plugin name \"{}\". Plugin names must start with a letter and contain only letters and numbers.",
                plugin.plugin_name
            ));
        }

        // Validate state binding
        if plugin.state_binding.binding == "__complex__" {
            eprintln!(
                "[analyzePluginUsage] Complex expression used for plugin \"{}\" state. This will be evaluated at runtime.",
                plugin.plugin_name
            );
        }

        // Validate version format if provided
        if let Some(version) = &plugin.version {
            if !semver_re.is_match(version) {
                eprintln!(
                    "[analyzePluginUsage] Invalid semver format for plugin \"{}\": {}",
                    plugin.plugin_name, version
                );
            }
        }
    }

    Ok(())
}
